"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[27813],{70739:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"JumpDriveGuiController","desc":"Drives the jump drive panel (`StarterGui.JumpDriveGui`, opened by the bench\'s\\n`JumpPromptPart` prompt) and feeds the party vote banner (`PartyVoteGui`)\\nfrom the single `JumpStateSync` payload, so the two can never disagree.\\nThe bench\'s `ChutePromptPart` hold prompt charges the drive: one\\n`ReqDepositJumpCharge` per finished hold fills it as far as the pool allows.\\n\\n- Panel: charge card with one JumpButton (points to the energy chute while\\n  Idle, click to start the vote while Ready), the UNKNOWN SIGNAL threat card, the\\n  destination card (Biome Selector picker, or the ERROR state), the status\\n  line, an in-panel vote row and the named roster.\\n- Banner: pushed while Voting to everyone except the vote opener and anyone\\n  with the panel open, so nobody sees two sets of vote buttons. Non-modal:\\n  abstaining is neutral, so a vote nobody sees always passes.\\n- Y/N vote keys belong to the banner: they work only while it shows.\\n\\nCountdowns extrapolate from server deadlines (`phaseEndsAt`,\\n`ThreatStateSync`), so every player sees the same number.","realm":["Client"],"source":{"line":26,"path":"src/StarterPlayer/StarterPlayerScripts/JumpDriveGuiController.client.luau"}}')}}]);